      static constexpr std::size_t MIN_SEGMENT_SIZE = 4;
      static constexpr std::size_t DEFAULT_PAGE_SIZE = 4096 / sizeof(T);

      using Segment = std::span<T>;
      struct MemorySegment
      {
        PageID pageID = MAIN_PAGEID;
        Segment segment;
      };

